import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"PlaceholderAPI 占位符","description":"","frontmatter":{},"headers":[],"relativePath":"modules/level/placeholders.md","filePath":"modules/level/placeholders.md","lastUpdated":0}`),a={name:`modules/level/placeholders.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="placeholderapi-占位符" tabindex="-1">PlaceholderAPI 占位符 <a class="header-anchor" href="#placeholderapi-占位符" aria-label="Permalink to “PlaceholderAPI 占位符”">​</a></h1><p>EmakiLevel 在安装 PlaceholderAPI 时注册扩展标识符 <code>emakilevel</code>。占位符适用于计分板、菜单、聊天格式、BossBar、ActionBar、其他插件文本模板，以及支持 PlaceholderAPI 的 GUI 插件。</p><p>如果 PlaceholderAPI 未安装，EmakiLevel 本体仍然可以正常运行，只是不会注册 <code>%emakilevel_*%</code> 外部占位符。</p><h2 id="玩家等级占位符" tabindex="-1">玩家等级占位符 <a class="header-anchor" href="#玩家等级占位符" aria-label="Permalink to “玩家等级占位符”">​</a></h2><p>玩家等级占位符需要有玩家上下文，例如计分板里的当前玩家、菜单拥有者或 PlaceholderAPI 请求传入的玩家。</p><table tabindex="0"><thead><tr><th>占位符</th><th>返回值</th></tr></thead><tbody><tr><td><code>%emakilevel_level_&lt;type&gt;%</code></td><td>当前等级。</td></tr><tr><td><code>%emakilevel_exp_&lt;type&gt;%</code></td><td>当前等级内经验。</td></tr><tr><td><code>%emakilevel_total_exp_&lt;type&gt;%</code></td><td>总经验。</td></tr><tr><td><code>%emakilevel_totalexp_&lt;type&gt;%</code></td><td>总经验，兼容无下划线写法。</td></tr><tr><td><code>%emakilevel_total_&lt;type&gt;%</code></td><td>总经验，短写法。</td></tr><tr><td><code>%emakilevel_required_exp_&lt;type&gt;%</code></td><td>升到下一级所需经验。</td></tr><tr><td><code>%emakilevel_requiredexp_&lt;type&gt;%</code></td><td>需求经验，兼容无下划线写法。</td></tr><tr><td><code>%emakilevel_required_&lt;type&gt;%</code></td><td>需求经验，短写法。</td></tr><tr><td><code>%emakilevel_progress_&lt;type&gt;%</code></td><td>当前等级进度，范围 0 到 1。</td></tr><tr><td><code>%emakilevel_progress_percent_&lt;type&gt;%</code></td><td>当前等级进度百分比，范围 0 到 100。</td></tr></tbody></table><p>示例：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>%emakilevel_level_main%</span></span>
<span class="line"><span>%emakilevel_exp_main%</span></span>
<span class="line"><span>%emakilevel_required_exp_main%</span></span>
<span class="line"><span>%emakilevel_progress_percent_main%</span></span>
<span class="line"><span>%emakilevel_level_combat%</span></span>
<span class="line"><span>%emakilevel_total_exp_mining%</span></span></code></pre></div><p>如果 <code>&lt;type&gt;</code> 不存在，或者玩家数据无法加载，占位符会返回空字符串。</p><h2 id="排行榜占位符" tabindex="-1">排行榜占位符 <a class="header-anchor" href="#排行榜占位符" aria-label="Permalink to “排行榜占位符”">​</a></h2><p>排行榜来自插件当前缓存的玩家等级数据。在线玩家和已加载过的数据会出现在缓存中；它不是数据库级全服离线扫描排行榜。</p><table tabindex="0"><thead><tr><th>占位符</th><th>返回值</th></tr></thead><tbody><tr><td><code>%emakilevel_top_&lt;type&gt;_&lt;rank&gt;_name%</code></td><td>指定名次的玩家名。</td></tr><tr><td><code>%emakilevel_top_&lt;type&gt;_&lt;rank&gt;_level%</code></td><td>指定名次的等级。</td></tr><tr><td><code>%emakilevel_top_&lt;type&gt;_&lt;rank&gt;_total_exp%</code></td><td>指定名次的总经验。</td></tr><tr><td><code>%emakilevel_top_&lt;type&gt;_&lt;rank&gt;_totalexp%</code></td><td>总经验，兼容无下划线写法。</td></tr><tr><td><code>%emakilevel_top_&lt;type&gt;_&lt;rank&gt;_total%</code></td><td>总经验，短写法。</td></tr></tbody></table><p>示例：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>%emakilevel_top_main_1_name%</span></span>
<span class="line"><span>%emakilevel_top_main_1_level%</span></span>
<span class="line"><span>%emakilevel_top_main_1_total_exp%</span></span>
<span class="line"><span>%emakilevel_top_combat_3_name%</span></span></code></pre></div><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>排行榜占位符解析格式固定为 <code>top_&lt;type&gt;_&lt;rank&gt;_&lt;field&gt;</code>。默认类型 ID 都不包含下划线；如果你自定义了包含下划线的类型 ID，玩家等级占位符可以正常解析，但排行榜占位符建议改用不含下划线的类型 ID，以避免歧义。</p></div><h2 id="数值格式" tabindex="-1">数值格式 <a class="header-anchor" href="#数值格式" aria-label="Permalink to “数值格式”">​</a></h2><p>EmakiLevel 会把数值格式化为适合展示的字符串：</p><ul><li>整数值输出整数，例如 <code>120</code>。</li><li>非整数值保留两位小数，例如 <code>12.50</code>。</li><li><code>progress</code> 是 0 到 1 的小数。</li><li><code>progress_percent</code> 是 0 到 100 的百分比数值，但不会自动附带 <code>%</code> 符号。</li></ul><p>示例计分板文本：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>主等级: Lv.%emakilevel_level_main%</span></span>
<span class="line"><span>主经验: %emakilevel_exp_main%/%emakilevel_required_exp_main%</span></span>
<span class="line"><span>进度: %emakilevel_progress_percent_main%%</span></span>
<span class="line"><span>战斗等级: Lv.%emakilevel_level_combat%</span></span>
<span class="line"><span>排行榜第一: %emakilevel_top_main_1_name% Lv.%emakilevel_top_main_1_level%</span></span></code></pre></div><p><code>%emakilevel_progress_percent_main%%</code> 中第一个 <code>%emakilevel_progress_percent_main%</code> 是占位符，最后一个 <code>%</code> 是显示给玩家看的百分号。</p><h2 id="常见用法" tabindex="-1">常见用法 <a class="header-anchor" href="#常见用法" aria-label="Permalink to “常见用法”">​</a></h2><h3 id="菜单-lore" tabindex="-1">菜单 Lore <a class="header-anchor" href="#菜单-lore" aria-label="Permalink to “菜单 Lore”">​</a></h3><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">lore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gray&gt;主等级: &lt;yellow&gt;Lv.%emakilevel_level_main%&lt;/yellow&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gray&gt;经验: &lt;green&gt;%emakilevel_exp_main%&lt;/green&gt;/&lt;green&gt;%emakilevel_required_exp_main%&lt;/green&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gray&gt;进度: &lt;aqua&gt;%emakilevel_progress_percent_main%%&lt;/aqua&gt;&quot;</span></span></code></pre></div><h3 id="条件插件" tabindex="-1">条件插件 <a class="header-anchor" href="#条件插件" aria-label="Permalink to “条件插件”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>%emakilevel_level_combat% &gt;= 20</span></span>
<span class="line"><span>%emakilevel_progress_percent_mining% &gt;= 75</span></span></code></pre></div><h3 id="聊天-称号展示" tabindex="-1">聊天/称号展示 <a class="header-anchor" href="#聊天-称号展示" aria-label="Permalink to “聊天/称号展示”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Lv.%emakilevel_level_main%] %player_name%: %message%</span></span></code></pre></div><h2 id="与内部动作变量的区别" tabindex="-1">与内部动作变量的区别 <a class="header-anchor" href="#与内部动作变量的区别" aria-label="Permalink to “与内部动作变量的区别”">​</a></h2><p>PlaceholderAPI 占位符是给外部插件读取的 <code>%emakilevel_*%</code> 变量。EmakiLevel 自己在 <code>types/&lt;type&gt;.yml &gt; upgrade.actions.*</code> 中提供的是动作上下文变量，例如 <code>%level%</code>、<code>%new_level%</code>、<code>%amount%</code>、<code>%failure_reason%</code>。两者写法都使用 <code>%key%</code> 风格，但作用域不同。</p><p>升级动作变量详见 <a href="./configuration.html#升级动作变量">配置详解</a>。</p>`,31)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};